{"command":"cat << 'EOF' > auto_play.py
import chess
import chess.engine
import subprocess

def get_board():
    out = subprocess.check_output(["./game.py", "status"]).decode("utf-8")
    for line in out.splitlines():
        if line.startswith("FEN:"):
            return chess.Board(line.split("FEN: ")[1].strip())
    return chess.Board()

def play():
    engine = chess.engine.SimpleEngine.popen_uci("/usr/local/bin/stockfish")

    while True:
        b = get_board()
        if b.is_game_over():
            print("Game over!")
            break

        result = engine.play(b, chess.engine.Limit(time=0.1))
        move = result.move.uci()
        print("Playing", move)
        out = subprocess.check_output(["./game.py", "move", move]).decode("utf-8")
        print(out)
        if "Game over" in out or "resigns" in out:
            break

    engine.quit()

play()
EOF
